insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Licence and supervision','A learner may drive only the class of vehicle authorised by the learner’s licence and, for a car, must be accompanied by a person who is licensed to drive that class of vehicle.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='driver-responsibilities';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Safe control','You must be able to control the vehicle, keep a proper lookout and avoid conduct that endangers people or property.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='driver-responsibilities';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Seat belts','Where seat belts are fitted, occupants must use them as required. Children must be restrained appropriately.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='driver-responsibilities';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Cell phones','Do not hold or operate a hand-held cellular or communication device while driving. A properly installed hands-free arrangement is the safer/legal way to communicate.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='driver-responsibilities';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Alcohol and drugs','Do not drive while under the influence of intoxicating liquor or a drug that affects your ability to drive. The safest exam rule is simple: if impaired, do not drive.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='driver-responsibilities';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Roadworthy condition','A vehicle used on a public road must be in a condition that is safe and complies with legal equipment requirements.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='vehicle-requirements';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Brakes','The service brake must be capable of controlling and stopping the vehicle. The parking/emergency brake must hold the vehicle when stationary.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='vehicle-requirements';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Steering','Steering must operate effectively without dangerous play or defects.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='vehicle-requirements';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Tyres','Tyres must be in a safe condition, correctly fitted and have legal tread. Never study only the tread number: also remember that cuts, exposed cords and dangerous damage matter.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='vehicle-requirements';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Lights','Use the required lights at night and when visibility is poor. Do not use lights in a way that dazzles other road users.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='vehicle-requirements';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Mirrors and glass','Keep windscreens/windows sufficiently clear for safe vision and use mirrors to maintain awareness around the vehicle.',4,6,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='vehicle-requirements';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Hooter','Use a hooter as a warning device, not unnecessarily or aggressively.',4,7,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='vehicle-requirements';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Speedometer','A motor vehicle designed for or capable of 60 km/h or more must have a working speedometer.',5,8,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='vehicle-requirements';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Keep left','Drive on the left side of the roadway unless a lawful reason or road layout requires otherwise.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='position-lanes';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Lane discipline','Stay within your lane, use lane markings correctly and do not change lanes until it is safe.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='position-lanes';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Lane changing','Before changing lanes: check mirrors, check the appropriate blind spot, signal if necessary, ensure a safe gap, then move smoothly.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='position-lanes';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Divided roads','On a divided road, use the carriageway intended for your direction of travel. Do not cross a median or dividing space except where permitted.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='position-lanes';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Shoulder use','The shoulder is not a normal driving lane. Limited daytime use may be permitted in specific circumstances, such as allowing another vehicle to pass, only when it is safe and visibility is adequate.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='position-lanes';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','General limits','Unless another limit is indicated: 60 km/h in an urban area, 100 km/h on a public road outside an urban area that is not a freeway, and 120 km/h on a freeway.',5,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='speed-following';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Posted limits','A displayed speed-limit sign overrides the general limit for the road section where it applies.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='speed-following';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Not a target','The maximum legal speed is not always a safe speed. Reduce speed for rain, darkness, pedestrians, traffic, bends, poor road surface or limited visibility.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='speed-following';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Following distance','Leave enough space to stop safely if the vehicle ahead brakes suddenly. Increase the gap in poor conditions.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='speed-following';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Normal side','Normally pass another vehicle travelling in the same direction on its right and at a safe distance.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='overtaking';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Return safely','Do not return to the left until you are safely clear of the vehicle you passed.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='overtaking';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','No speeding to pass','You may not exceed the speed limit merely because you are overtaking.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='overtaking';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Passing on the left','Passing on the left is allowed only in lawful circumstances and when it can be done safely, for example where the vehicle ahead is turning right or where lanes permit it.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='overtaking';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Do not overtake blindly','Never overtake where road signs/markings prohibit it or where you cannot see enough clear road ahead to complete the manoeuvre safely.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='overtaking';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Approach','Slow down, observe signs/signals and be prepared to stop.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='intersections';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Traffic circle','At a traffic circle, yield to traffic approaching from your right within the circle unless a traffic officer or sign directs otherwise.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='intersections';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Turning','Before turning, position correctly, signal in time, check mirrors/blind spots and yield to traffic or pedestrians that have priority.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='intersections';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Blocked intersection','Do not enter an intersection unless there is enough space beyond it for you to clear the intersection.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='intersections';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Uncontrolled situations','Where no sign or signal settles priority, approach cautiously and apply the applicable right-of-way rule rather than assuming other drivers will stop.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='intersections';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Difference','Stopping is keeping a vehicle stationary for a shorter necessary purpose; parking is keeping it stationary longer than is reasonably necessary for loading/unloading people or goods.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='stopping-parking';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Never obstruct','Do not stop or park where you create danger, obstruct traffic or contravene a sign/marking.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='stopping-parking';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Common prohibited places','Expect test questions around intersections, pedestrian crossings, railway crossings, narrow roads, bridges/tunnels, fire hydrants, driveways and places where visibility is restricted.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='stopping-parking';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Parking position','Park within marked bays where provided and close to the kerb/edge as required without blocking pedestrians or entrances.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='stopping-parking';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Permitted traffic','Certain slow, vulnerable or unsuitable vehicles are prohibited on freeways, including animal-drawn vehicles, pedal cycles and specified small motorcycles/vehicles.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='freeways';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Stopping','Do not stop on a freeway except where directed, in a designated area, or because of circumstances beyond your control.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='freeways';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Pedestrians','Pedestrians are not normally permitted on a freeway.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='freeways';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Merging','Cooperate with vehicles merging from an on-ramp and maintain safe space. Do not make sudden lane changes.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='freeways';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Keep left','Keep left and use the right lane mainly for overtaking where the roadway has multiple lanes in your direction.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='freeways';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Crossings','Approach pedestrian crossings cautiously and yield/stop as required.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='pedestrians';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Children and vulnerable pedestrians','Reduce speed and be prepared for unpredictable movement near schools, buses, parked vehicles and crowded areas.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='pedestrians';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Do not intimidate','Do not use speed, hooter or vehicle position to force a pedestrian out of your path.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='pedestrians';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Towing','Towing must comply with legal coupling, safety and distance requirements. Drive slowly enough to keep the combination under control.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='loads-towing';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Loads','Loads must be secure and must not fall, drag, obstruct the driver’s view or create a danger.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='loads-towing';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Projections','Loads that project beyond the vehicle may require prescribed warning flags/reflectors and are subject to maximum projection rules.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='loads-towing';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Passengers','Do not carry passengers in a way that is unsafe or prohibited. Goods vehicles have specific rules for carrying people.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='loads-towing';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Stop','If involved in a crash, stop the vehicle.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='accidents';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Check and assist','Determine whether anyone is injured and provide reasonable assistance / obtain emergency help.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='accidents';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Information','Exchange required identifying and vehicle information with the relevant people.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='accidents';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Report','Report the accident to police when legally required, including where there are injuries or other prescribed circumstances.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='accidents';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Do not interfere','Do not unlawfully leave the scene, conceal evidence or consume alcohol after the crash before required testing/reporting is dealt with.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='accidents';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Reckless/negligent driving','Never drive recklessly or negligently. The law considers both the driving behaviour and the circumstances.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Inconsiderate driving','Do not drive without reasonable consideration for other road users.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Road damage','Do not intentionally spin/drag wheels or use a vehicle in a way that damages the road except where an emergency makes an action unavoidable.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Emergency vehicles','Give way to emergency vehicles displaying the prescribed warning signals and create a safe path without causing another danger.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Exam fact','Keep left; normally overtake on the right.',5,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Exam fact','Do not exceed the speed limit while overtaking.',5,6,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Exam fact','Do not enter an intersection you cannot clear.',5,7,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Exam fact','At a traffic circle, expect to yield to traffic from your right unless signs/signals say otherwise.',5,8,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Exam fact','Freeway stopping is allowed only in limited circumstances.',5,9,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Exam fact','Traffic officers’ lawful directions take precedence over ordinary signs/signals.',5,10,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Exam fact','Regulatory signs and regulatory road markings must be obeyed.',5,11,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Exam fact','Safe driving can require a speed lower than the posted maximum.',5,12,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='rules' and l.slug='safe-driving';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Regulatory','Purpose: Controls or restricts behaviour. Visual clue: Usually round; important exceptions include STOP and YIELD. Driver action: Obey.',4,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='signs' and l.slug='sign-families';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Warning','Purpose: Warns of danger/hazard ahead. Visual clue: Usually triangular. Driver action: Slow down, observe, prepare.',4,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='signs' and l.slug='sign-families';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Guidance','Purpose: Helps with routes/directions. Visual clue: Usually rectangular. Driver action: Follow route information.',4,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='signs' and l.slug='sign-families';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Information','Purpose: Provides useful information. Visual clue: Usually rectangular. Driver action: Use information.',4,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='signs' and l.slug='sign-families';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Road markings','Purpose: Controls, guides and warns on the road surface. Visual clue: Lines, arrows, words, symbols. Driver action: Obey regulatory markings.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='signs' and l.slug='sign-families';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Traffic signals','Purpose: Controls vehicles/pedestrians. Visual clue: Coloured lights/arrows. Driver action: Obey the displayed signal.',4,6,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='signs' and l.slug='sign-families';
