insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Recognition rule','Never answer a sign question from colour alone. Use shape + symbol + road context.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='signs' and l.slug='sign-families';
