insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Tachometer / rev counter','Shows engine speed in revolutions per minute where fitted.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='dashboard';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Oil-pressure warning lamp','Warns of an engine lubrication/oil-pressure problem; continuing to drive may cause damage.',4,6,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='dashboard';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Battery/charging warning lamp','Warns that the charging system may not be charging correctly.',4,7,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='dashboard';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Brake warning lamp','May indicate the parking brake is applied or a braking-system warning, depending on vehicle design.',4,8,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='dashboard';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','ABS warning lamp','Warns of an anti-lock braking system fault when it remains on unexpectedly.',4,9,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='dashboard';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Airbag/SRS warning lamp','Warns of a supplemental restraint system fault.',4,10,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='dashboard';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Seat-belt warning','Reminds occupants to fasten seat belts.',4,11,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='dashboard';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Demister/defogger','Helps clear mist/condensation from windows.',4,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='visibility';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Bonnet release','Releases the bonnet/hood latch.',4,8,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='primary-controls';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Boot/tailgate release','Releases the luggage compartment/tailgate where fitted.',4,9,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='primary-controls';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Moving off in a manual car','Observe → signal if needed → clutch/gear → obtain clutch control → release parking brake → move off smoothly → cancel signal.',4,10,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='primary-controls';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Changing gear','Ease accelerator → depress clutch → select appropriate gear → release clutch smoothly → reapply accelerator as needed.',4,11,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='primary-controls';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Stopping','Observe traffic → signal if needed → ease accelerator → brake progressively → clutch near stopping point in a manual car → stop under control → secure vehicle if remaining stationary.',4,12,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='primary-controls';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Turning','Mirrors/observation → signal → correct road position → reduce speed/select gear → check danger areas → steer through turn → accelerate smoothly when safe.',4,13,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='primary-controls';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Lane change','Mirrors → indicator → blind-spot check → safe gap → smooth lateral move → cancel indicator.',4,14,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='primary-controls';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Emergency warning','Control the vehicle first. Warn other road users with appropriate lights/hooter only when doing so helps safety.',4,15,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='primary-controls';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'rule','Blind spots','Mirrors do not show every area around a car. Before moving sideways or moving off where another road user could be hidden, check the relevant blind spot by looking directly.',5,6,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='controls' and l.slug='visibility';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','General urban speed limit','60 km/h. Unless a different speed limit is indicated.',60,'km/h',5,1,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','General non-freeway speed limit outside an urban area','100 km/h. Unless another limit is indicated.',100,'km/h',5,2,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','General freeway speed limit','120 km/h. Unless another limit is indicated.',120,'km/h',5,3,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Bus/minibus conveying persons for reward','100 km/h. Specific class limit in the learner manual.',100,'km/h',5,4,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Certain heavy goods/vehicle combinations','80 km/h. Applies to specified heavy vehicle classes in the learner manual.',80,'km/h',5,5,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Speedometer requirement','60 km/h capability. A motor vehicle designed for or capable of 60 km/h or more must have a working speedometer.',60,'km/h capability',5,6,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Learner’s licence validity','24 months. Government service information states it cannot be extended.',24,'months',5,7,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Rules of the road pass mark','22 / 28. Minimum official mark.',22,'/ 28',5,8,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Road traffic signs pass mark','23 / 28. Minimum official mark.',23,'/ 28',5,9,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Vehicle controls pass mark','6 / 8. Minimum official mark.',6,'/ 8',5,10,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Total questions in the standard split','64. 28 rules + 28 signs + 8 controls.',64,'',5,11,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Light learner vehicle mass category','up to 3 500 kg GVM. National service page describes Code 2 this way; provincial wording may refer to Code B/old Code 8 vehicle class.',null,'to 3 500 kg GVM',5,12,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,numeric_value,unit,importance,position,is_published) select l.id,'number','Visibility for limited daytime shoulder use','150 m. Learner manual road-marking guidance uses this visibility threshold in the stated circumstances.',150,'m',5,13,true from public.lessons l join public.modules mo on mo.id=l.module_id where mo.slug='numbers' and l.slug='core-numbers';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','MUST vs MAY','MUST is compulsory. MAY means permitted, not required.',5,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','NOT / EXCEPT','Circle these words mentally. They reverse the question.',5,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Maximum speed vs safe speed','A speed limit is a maximum, not a promise that the speed is safe.',5,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Right of way vs safety','Having priority does not allow you to cause a collision.',5,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Signal vs permission','An indicator communicates intention. It does not force other road users to let you in.',5,5,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Green light vs blocked intersection','Green means you may proceed only if you can clear the intersection safely.',5,6,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','No parking vs no stopping','These are not the same restriction. Learn the exact wording of the sign.',5,7,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Overtaking','The normal rule is pass on the right, but lawful exceptions allow passing on the left in specified situations.',5,8,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Shoulder','It is not an extra lane. Limited use is conditional.',5,9,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Traffic officer','A lawful direction by a traffic officer overrides the normal instruction you would otherwise follow.',5,10,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Temporary roadworks','Temporary signs/controls apply to the temporary layout even if the normal road markings look different.',5,11,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Road marking nearest you','With combination barrier/broken lines, the line on your side is crucial.',5,12,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Mirrors','Checking mirrors does not replace checking a blind spot when a vehicle/cyclist could be hidden.',5,13,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Hazard lights','They warn of danger; they do not make illegal parking legal.',5,14,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','High beam','More light is not always better. High beam must not dazzle others.',5,15,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Overtaking speed','You may not exceed the speed limit just to complete an overtake.',5,16,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Freeway stop','Normally prohibited, but there are exceptions such as a designated area, lawful direction or circumstances beyond your control.',5,17,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Vehicle controls','A question may show a component and ask what it does, rather than simply asking its name.',5,18,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'trap','Similar signs','Study the action required, not only the sign name. Two signs can look similar but require different actions.',5,19,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Question reading','Read the full question before looking at the answers.',5,20,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Spot reversal words','NOT, EXCEPT, LEAST, MAY NOT.',5,21,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Question reading','Identify whether the question asks about law, safety, a sign, a road marking or a vehicle control.',5,22,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Question reading','Eliminate answers that are clearly unsafe or contradict a regulatory instruction.',5,23,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Question reading','Check whether an exception is being tested.',5,24,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'tip','Question reading','Choose the most precise answer, not the one that is merely generally sensible.',5,25,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Stop / Yield','Stop always requires a complete stop; yield requires giving priority and stopping only when necessary.',5,26,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','No parking / No stopping','No stopping is stricter.',5,27,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Warning / Regulatory','Warning prepares you for danger; regulatory tells you what you must/must not do.',5,28,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Guidance / Information','Both help rather than command, but guidance is route/direction focused while information gives general road-user information.',5,29,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Lane line / Barrier line','A broken lane line may be crossed when safe; a barrier line restricts crossing.',5,30,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'definition','Dipped / Main beam','Dipped beam avoids dazzling; main beam gives longer illumination where appropriate.',5,31,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='traps' and l.slug='question-traps';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'number','Rules section','28 questions; pass mark 22.',5,1,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='mock' and l.slug='mock-format';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'number','Signs section','28 questions; pass mark 23.',5,2,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='mock' and l.slug='mock-format';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'number','Controls section','8 questions; pass mark 6.',5,3,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='mock' and l.slug='mock-format';
insert into public.facts(lesson_id,fact_type,title,content,importance,position,is_published) select l.id,'number','Total','64 questions. Each section must meet its own pass mark.',5,4,true from public.lessons l join public.modules m on m.id=l.module_id where m.slug='mock' and l.slug='mock-format';
