  insert into public.question_options(question_id,option_text,is_correct,position) values(qid,'Either side at any time',false,3);
  insert into public.questions(module_id,type,prompt,explanation,difficulty,position,is_published) select id,'multiple_choice','May you exceed the speed limit while overtaking?','The speed limit still applies while overtaking.','easy',5,true from public.modules where slug='rules' returning id into qid;
  insert into public.question_options(question_id,option_text,is_correct,position) values(qid,'Yes, briefly',false,1);
