  insert into public.questions(module_id,type,prompt,explanation,difficulty,position,is_published) select id,'multiple_choice','A green traffic light allows you to enter an intersection when:','Do not block an intersection.','easy',6,true from public.modules where slug='rules' returning id into qid;
